#include <stdio.h>

int giam_gia(int gia) {
    if (gia >= 100000)
        return gia - gia / 10;
    return gia;
}

int main(void) {
    int gia;
    scanf("%d", &gia);
    printf("%d\n", giam_gia(gia));
    return 0;
}
